commands.command:
$ErrorActionPreference = 'Stop'
$project = (Get-Location).Path
$expectedProject = '<user-home>\Desktop\project\codex_docs'
if ($project -ne $expectedProject) { throw 'Unexpected workspace' }
$reports = (Resolve-Path -LiteralPath '.docs-tools/reports/paos-aud-g6').Path
$target = [IO.Path]::GetFullPath((Join-Path $reports 'host-target'))
if ($target -ne '<user-home>\Desktop\project\codex_docs\.docs-tools\reports\paos-aud-g6\host-target') { throw 'Boundary mismatch' }
if (Test-Path -LiteralPath $target) { throw 'Target already exists; not newly-created empty' }
New-Item -ItemType Directory -Path $target | Out-Null
if (@(Get-ChildItem -LiteralPath $target -Force).Count -ne 0) { throw 'Target is not empty' }
Write-Output ('Validated new empty target: ' + $target)
git -C $target init
if ($LASTEXITCODE -ne 0) { exit $LASTEXITCODE }
git -C $target rev-parse --show-toplevel

